#! /usr/bin/env python3

from argparse import ArgumentParser

BANNED_CATEGORIES = ("Cc", "Cf", "Co")
MAX_CODEPOINT = 0x10FFFF

HEADER_BANNER = """
/* This file generated by devtools/gen-unicode-category.py */
/* Do not modify this file!!! Modify the script, or regenerate from a new
 * UnicodeData.txt, instead */
"""


def parse_unicode_data(path):
    assigned = []
    pending_range_start = None
    pending_range_category = None

    with open(path, encoding="utf-8") as f:
        for line in f:
            fields = line.rstrip("\n").split(";")
            codepoint = int(fields[0], 16)
            name = fields[1]
            category = fields[2]

            if name.endswith(", First>"):
                pending_range_start = codepoint
                pending_range_category = category
                continue

            if name.endswith(", Last>"):
                assert pending_range_start is not None
                assert pending_range_category == category
                assigned.append((pending_range_start, codepoint, category))
                pending_range_start = None
                pending_range_category = None
                continue

            assigned.append((codepoint, codepoint, category))

    assigned.sort(key=lambda r: r[0])
    return assigned


def compute_banned_ranges(assigned):
    banned = []

    for start, end, category in assigned:
        if category in BANNED_CATEGORIES:
            banned.append((start, end))

    next_free = 0
    for start, end, _category in assigned:
        if start > next_free:
            banned.append((next_free, start - 1))
        next_free = max(next_free, end + 1)
    if next_free <= MAX_CODEPOINT:
        banned.append((next_free, MAX_CODEPOINT))

    banned.sort(key=lambda r: r[0])

    merged = []
    for start, end in banned:
        if merged and start <= merged[-1][1] + 1:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return merged


def write_header(path, guard):
    with open(path, "w", encoding="utf-8") as f:
        f.write(HEADER_BANNER)
        f.write(
            f"""
#ifndef {guard}
#define {guard}
#include "config.h"
#include <ccan/short_types/short_types.h>
#include <stdbool.h>

bool unicode_is_banned_codepoint(u32 cp);

#endif /* {guard} */
"""
        )


def write_source(path, header_path, ranges, unicode_version):
    with open(path, "w", encoding="utf-8") as f:
        f.write(HEADER_BANNER)
        f.write(f"/* Generated from Unicode {unicode_version} UnicodeData.txt */\n")
        f.write(
        f'\n'
        f'#include "config.h"\n'
        f'#include <ccan/array_size/array_size.h>\n'
        f'#include "{header_path}"\n'
        f'#include <stddef.h>\n'
        f'\n'
        f'struct unicode_range {{\n'
        f'\tu32 start, end;\n'
        f'}};\n'
        f'\n'
        f'/* Sorted, non-overlapping, coalesced ranges banned as Cc/Cf/Co/Cn. */\n'
        f'static const struct unicode_range banned_ranges[] = {{\n'
        )
        for start, end in ranges:
            f.write(f"\t{{ 0x{start:06X}, 0x{end:06X} }},\n")
        f.write(
        '};\n'
        '\n'
        'bool unicode_is_banned_codepoint(u32 cp)\n'
        '{\n'
        '\tsize_t lo = 0, hi = ARRAY_SIZE(banned_ranges);\n'
        '\n'
        '\twhile (lo < hi) {\n'
        '\t\tsize_t mid = lo + (hi - lo) / 2;\n'
        '\t\tconst struct unicode_range *r = &banned_ranges[mid];\n'
        '\n'
        '\t\tif (cp < r->start)\n'
        '\t\t\thi = mid;\n'
        '\t\telse if (cp > r->end)\n'
        '\t\t\tlo = mid + 1;\n'
        '\t\telse\n'
        '\t\t\treturn true;\n'
        '\t}\n'
        '\treturn false;\n'
        '}\n'
        )


def main():
    parser = ArgumentParser(description=__doc__)
    parser.add_argument("unicodedata", help="Path to UnicodeData.txt")
    parser.add_argument(
        "outbase",
        help="Output basename, common/unicode_category "
        "(writes .c and .h)",
    )
    parser.add_argument(
        "--unicode-version",
        default="unknown",
        help="Unicode version string to record in a comment",
    )
    args = parser.parse_args()

    assigned = parse_unicode_data(args.unicodedata)
    ranges = compute_banned_ranges(assigned)

    header_path = args.outbase + ".h"
    source_path = args.outbase + ".c"
    guard = "LIGHTNING_" + args.outbase.upper().replace("/", "_") + "_H"
    write_header(header_path, guard)
    write_source(source_path, header_path, ranges, args.unicode_version)

    print(f"Wrote {header_path} and {source_path}: {len(ranges)} banned ranges")


if __name__ == "__main__":
    main()
